	CONSTRAINT "consent_rules_months" CHECK (("consent_rules"."rule" = 'months' and "consent_rules"."months" between 1 and 120) or ("consent_rules"."rule" <> 'months' and "consent_rules"."months" is null))
);
CREATE TABLE "consent_templates" (
