  ('98ffe61e-4e6e-5cfa-b5ec-e058c0721602', false, true, false, true, true, true, '{"eyebrowAr":"العيادة · منذ ١٩٩٦","eyebrowEn":"The Practice · Since 1996","headlineAr":"رعاية جلدية وتجميلية وطب أسنان على أيدي أطباء متخصصين","headlineEn":"Specialist dermatology, aesthetic and dental care","taglineAr":"الجلدية وجراحة التجميل واستعادة الشعر وطب الأسنان، تحت سقف واحد منذ عام ١٩٩٦.","taglineEn":"Dermatology, plastic surgery, hair restoration and dentistry, under one roof since 1996.","aboutTitleAr":"عن عيادات ديرما","aboutTitleEn":"About Derma Clinics","aboutAr":"تأسست عيادات ديرما عام ١٩٩٦، وتضم اليوم أربعة أقسام: الأمراض الجلدية والطب التجميلي، وزراعة الشعر، وجراحة التجميل، وطب الأسنان. يبدأ كل علاج بكشف لدى طبيب القسم، يشرح فيه التشخيص والخيارات والتكلفة قبل أن يقرّر المريض.","aboutEn":"Derma Clinics was founded in 1996 and today has four departments: dermatology and aesthetic medicine, hair restoration, plastic surgery, and dentistry. Every treatment begins with an examination by a doctor in that department, who explains the diagnosis, the options and the cost before the patient decides.","quoteAr":"نشرح لكل مريض التشخيص والخيارات قبل أي علاج، ولا نوصي إلا بما يحتاجه.","quoteEn":"Every patient hears the diagnosis and the options before any treatment, and is advised only what they need.","clinicsAr":"أربعة أقسام، لكل قسم أطباؤه وغرفه، ولكل مريض ملف طبي واحد تطّلع عليه الأقسام التي يراجعها.","clinicsEn":"Four departments, each with its own doctors and rooms. Each patient has one medical record, shared by the departments they visit.","doctorsAr":"استشاريون وأخصائيون في الأمراض الجلدية وزراعة الشعر وجراحة التجميل وطب الأسنان.","doctorsEn":"Consultants and specialists in dermatology, hair restoration, plastic surgery and dentistry.","findAr":"الرياض وجدة. الزيارة بموعد مسبق.","findEn":"Riyadh and Jeddah. Visits by appointment.","footerAr":"عيادات ديرما. الأمراض الجلدية والطب التجميلي وزراعة الشعر وجراحة التجميل وطب الأسنان، منذ ١٩٩٦.","footerEn":"Derma Clinics. Dermatology, aesthetic medicine, hair restoration, plastic surgery and dentistry, since 1996.","since":1996,"phone":"9200 33055","whatsapp":"+966550883080","instagram":"dermaclinics","x":"dermaclinics","tiktok":"derma_clinics","departments":[{"key":"skin","nameAr":"طب الجلدية والطب التجميلي وزراعة الشعر","nameEn":"Dermatology, Aesthetic Medicine & Hair Transplantation","textAr":"تشخيص وعلاج أمراض الجلد والشعر والأظافر، والطب التجميلي والليزر.","textEn":"Diagnosis and treatment of skin, hair and nail conditions, aesthetic medicine and laser.","specialties":["skin","hair"]},{"key":"dental","nameAr":"طب الأسنان","nameEn":"Dental Care","textAr":"طب الأسنان العام والتجميلي، والزراعة والتقويم، وطب أسنان الأطفال.","textEn":"General and cosmetic dentistry, implants, orthodontics and children''s dentistry.","specialties":["dental"]},{"key":"plastic","nameAr":"جراحة التجميل","nameEn":"Plastic Surgery","textAr":"جراحات تجميل الوجه والجسم.","textEn":"Facial and body plastic surgery.","specialties":["plastic"]}],"specialties":[{"key":"skin","nameAr":"الجلدية والطب التجميلي","nameEn":"Dermatology & Aesthetic Medicine","textAr":"طب الجلدية العلاجي والتجميلي وطب الليزر.","textEn":"Medical and aesthetic dermatology and laser medicine.","bookable":true},{"key":"dental","nameAr":"طب الأسنان التجميلي والعام","nameEn":"Cosmetic & General Dentistry","textAr":"طب الأسنان العام والترميمي والتجميلي.","textEn":"General, restorative and cosmetic dentistry."},{"key":"hair","nameAr":"زراعة واستعادة الشعر","nameEn":"Hair Restoration & Transplantation","textAr":"العلاج الطبي لتساقط الشعر، وزراعة الشعر.","textEn":"Medical treatment of hair loss, and hair transplantation."},{"key":"plastic","nameAr":"جراحة التجميل","nameEn":"Plastic Surgery","textAr":"جراحات تجميل الوجه والجسم.","textEn":"Facial and body plastic surgery."}],"silos":[{"key":"skin","dept":"skin","nameAr":"الأمراض الجلدية والطب التجميلي","nameEn":"Dermatology & Aesthetic Medicine","items":[{"ar":"الأمراض الجلدية","en":"Medical Dermatology"},{"