grant select, insert on public.membership_payments, public.membership_visits to clinic_app;

-- Supabase's Data API roles must never reach these tables (Data API is off; belt and braces).
do $$
begin
  if exists (select from pg_roles where rolname = 'anon') then
    execute 'revoke all on all tables in schema public from anon, authenticated';
  end if;
end $$;

-- ─── Row-Level Security ─────────────────────────────────────────────────────
-- Tenant tables: a row is visible/writable only when its tenant_id = current clinic.
do $$
declare
  t text;
begin
  foreach t in array array[
    'branches', 'departments', 'tenant_members', 'rooms', 'devices', 'services',
    'staff_schedules', 'patients', 'audit_logs',
    'tenant_settings', 'branch_holidays', 'patient_medical_flags', 'appointments',
    'time_blocks', 'reservations', 'reschedule_requests', 'package_templates',
    'patient_packages', 'package_payments', 'package_session_events', 'files',
    'consent_templates', 'patient_consents', 'clinical_notes', 'clinical_note_addenda', 'clinical_note_versions',
    'verification_codes', 'rate_limit_hits', 'patient_sessions',
    'conversations', 'messages', 'message_templates', 'message_dispatches', 'webhook_events',
    'push_log', 'consent_rules', 'concern_events',
    'push_subscriptions', 'notification_prefs', 'schedule_exceptions',
    'platform_statements', 'platform_payments', 'support_grants', 'service_practitioners',
    'care_team', 'billing_items', 'visit_charges', 'visit_orders', 'visit_checkouts',
    'dental_chart_entries', 'dental_plan_items', 'lab_cases',
    'membership_plans', 'patient_memberships', 'membership_payments', 'membership_visits',
    'lab_reports', 'lab_values', 'lab_requests', 'clinical_photos'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force row level security', t);
    execute format(
      'create policy %I on public.%I for all to clinic_app
         using (tenant_id = public.app_current_tenant())
         with check (tenant_id = public.app_current_tenant())',
      t || '_tenant_isolation', t);
  end loop;
end $$;

-- Branch-scoped tables: ALSO limited to the user's allowed branches ("restrictive" = AND).
do $$
declare
  t text;
begin
  foreach t in array array['appointments', 'time_blocks', 'reservations', 'reschedule_requests'] loop
    execute format(
      'create policy %I on public.%I as restrictive for all to clinic_app
         using (public.app_branch_allowed(branch_id))
         with check (public.app_branch_allowed(branch_id))',
      t || '_branch_scope', t);
  end loop;
end $$;

-- Nurse / assistant: does the signed-in user assist the doctor whose user id is given?
-- (care_team links the assistant's and the doctor's clinic memberships; read through RLS.)
create or replace function public.app_assists(doctor_user_id text) returns boolean
  language sql stable
  set search_path = ''
as $$
  select public.app_has_role('assistant') and exists (
    select 1
      from public.care_team ct
      join public.tenant_members a on a.id = ct.assistant_member_id and a.tenant_id = ct.tenant_id
      join public.tenant_members d on d.id = ct.practitioner_member_id and d.tenant_id = ct.tenant_id
     where a.user_id = public.app_current_user()
       and d.user_id = doctor_user_id
       and a.deactivated_at is null and d.deactivated_at is null
  )
$$;
grant execute on function public.app_assists(text) to clinic_app;

-- Clinical notes: the practitioner role — or a nurse / assistant for the notes of the doctors
-- she works with (care_team). Addenda: practitioners only. Enforced by the database itself.
create policy clinical_notes_practitioners_only on public.clinical_notes as restrictive
  for all to clinic_app
  using (public.app_has_role('practitioner') or public.app_assists(author_user_id))
  with check (public.app_has_role('practitioner') or public.app_assists(author_user_id));
create policy clinical_note_versions_clinical_only on public.clinical_note_versions as restrictive
  for all to clinic_app
  using (public.app_has_role('practitioner') or exists (
    select 1 from public.clinical_notes n
     where n.tenant_id = clinical_note_versions.tenant_id and n.id = clinical_note_versions.note_id
       and public.app_assists(n.author_user_id)))
  with check (public.app_has_role('practitioner'));
create policy clinical_note_addenda_practitioners_only on public.clinical_note_addenda as restrictive
  for all to clinic_app
  using (public.app_has_role('practitioner'))
  with check (public.app_has_role('practitioner'));

-- Notes are written in the doctor's (author's) own name; only the author edits a draft — or
-- their nurse / assistant, who prepares it and may post it with the visit (never starts one).
create policy clinical_notes_author_insert on public.clinical_notes as restrictive
  for insert to clinic_app with check (
    author_user_id = public.app_current_user()
    or (public.app_assists(author_user_id) and status = 'draft'));
create policy clinical_notes_author_update on public.clinical_notes as restrictive
  for update to clinic_app
  using (author_user_id = public.app_current_user() or public.app_assists(author_user_id))
  with check (author_user_id = public.app_current_user() or public.app_assists(author_user_id));
create policy clinical_note_addenda_author_insert on public.clinical_note_addenda as restrictive
  for insert to clinic_app with check (author_user_id = public.app_current_user());

-- A visit's invoice codes and orders can change only while the visit is open: once it is
-- posted (completed) — or cancelled / no-show — they are locked, whatever the app does.
create or replace function public.app_visit_open(appt uuid) returns boolean
  language sql stable
  set search_path = ''
as $$
  select exists (
    select 1 from public.appointments a
     where a.id = appt and a.status not in ('completed', 'cancelled', 'no_show')
  )
$$;
grant execute on function public.app_visit_open(uuid) to clinic_app;

do $$
declare
  t text;
begin
  foreach t in array array['visit_charges', 'visit_orders'] loop
    execute format(
      'create policy %I on public.%I as restrictive for insert to clinic_app
         with check (public.app_visit_open(appointment_id))', t || '_open_insert', t);
    execute format(
      'create policy %I on public.%I as restrictive for delete to clinic_app
         using (public.app_visit_open(appointment_id))', t || '_open_delete', t);
  end loop;
end $$;

-- A checkout only for a posted (completed) visit.
create or replace function public.app_visit_completed(appt uuid) returns boolean
  language sql stable
  set search_path = ''
as $$
  select exists (select 1 from public.appointments a where a.id = appt and a.status = 'completed')
$$;
grant execute on function public.app_visit_completed(uuid) to clinic_app;
create policy visit_checkouts_completed_insert on public.visit_checkouts as restrictive
  for insert to clinic_app with check (public.app_visit_completed(appointment_id));

-- Dental chart = clinical: only doctors and nurses read or add to it.
create policy dental_chart_entries_clinical_only on public.dental_chart_entries as restrictive
  for all to clinic_app
  using (public.app_has_role('practitioner') or public.app_has_role('assistant'))
  with check (public.app_has_role('practitioner') or public.app_has_role('assistant'));
-- Lab results are clinical: only doctors and nurses read or add them (never reception or an
-- admin alone).
create policy lab_reports_clinical_only on public.lab_reports as restrictive
  for all to clinic_app
  using (public.app_has_role('practitioner') or public.app_has_role('assistant'))
  with check (public.app_has_role('practitioner') or public.app_has_role('assistant'));
create policy lab_values_clinical_only on public.lab_values as restrictive
  for all to clinic_app
  using (public.app_has_role('practitioner') or public.app_has_role('assistant'))
  with check (public.app_has_role('practitioner') or public.app_has_role('assistant'));
create policy lab_requests_clinical_only on public.lab_requests as restrictive
  for all to clinic_app
  using (public.app_has_role('practitioner') or public.app_has_role('assistant'))
  with check (public.app_has_role('practitioner') or public.app_has_role('assistant'));
-- Clinical photos (before / after): doctors, nurses and the clinic admin see them; only doctors
-- and nurses add or void them. Never reception, never patients (patient wall: not listed).
create policy clinical_photos_clinical_read on public.clinical_photos as restrictive
  for select to clinic_app
  using (public.app_has_role('practitioner') or public.app_has_role('assistant')
         or public.app_has_role('clinic_admin'));
create policy clinical_photos_clinical_insert on public.clinical_photos as restrictive
  for insert to clinic_app
  with check (public.app_has_role('practitioner') or public.app_has_role('assistant'));
create policy clinical_photos_clinical_update on public.clinical_photos as restrictive
  for update to clinic_app
  using (public.app_has_role('practitioner') or public.app_has_role('assistant'))
  with check (public.app_has_role('practitioner') or public.app_has_role('assistant'));
-- Treatment plan: everyone in the clinic reads it (booking, estimates); doctors and nurses change it.
create policy dental_plan_items_clinical_insert on public.dental_plan_items as restrictive
  for insert to clinic_app
  with check (public.app_has_role('practitioner') or public.app_has_role('assistant'));
create policy dental_plan_items_clinical_update on public.dental_plan_items as restrictive
  for update to clinic_app
  using (public.app_has_role('practitioner') or public.app_has_role('assistant'));

-- Clinic directory: readable, never writable by the app.
alter table public.tenants enable row level security;
alter table public.tenants force row level security;
create policy tenants_read on public.tenants for select to clinic_app using (true);
-- New clinics are created only by public.app_create_clinic() (runs as its owner, not clinic_app).
create policy tenants_create on public.tenants for insert
  with check (current_user <> 'clinic_app');
create policy tenant_settings_create on public.tenant_settings for insert
  with check (current_user <> 'clinic_app');
-- The platform functions above (running as the table owner) may also read and update the directory.
create policy tenants_owner_read on public.tenants for select
  using (current_user <> 'clinic_app');
create policy tenants_owner_update on public.tenants for update
  using (current_user <> 'clinic_app') with check (current_user <> 'clinic_app');

-- Platform billing rows: written only by platform work (the platform owner, or the daily job
-- acting for the platform), never by clinic staff. The billing rule above may read them.
do $$
declare
  t text;
begin
  foreach t in array array['platform_statements', 'platform_payments'] loop
    execute format(
      'create policy %I on public.%I as restrictive for insert to clinic_app
         with check (public.app_has_role(''platform_owner''))', t || '_platform_insert', t);
    execute format(
      'create policy %I on public.%I as restrictive for update to clinic_app
         using (public.app_has_role(''platform_owner''))', t || '_platform_update', t);
    execute format(
      'create policy %I on public.%I for select using (current_user <> ''clinic_app'')',
      t || '_owner_read', t);
  end loop;
end $$;

-- Support grants: only a clinic admin of this clinic (never a platform owner, even during a
-- support session) may give or end access.
create policy support_grants_admin_insert on public.support_grants as restrictive
  for insert to clinic_app
  with check (public.app_has_role('clinic_admin') and not public.app_is_platform_owner());
create policy support_grants_admin_update on public.support_grants as restrictive
  for update to clinic_app
  using (public.app_has_role('clinic_admin') and not public.app_is_platform_owner());
-- The gate functions (running as the table owner) read memberships and grants.
create policy tenant_members_owner_read on public.tenant_members for select
  using (current_user <> 'clinic_app');
create policy support_grants_owner_read on public.support_grants for select
  using (current_user <> 'clinic_app');

-- The platform gate on every table holding patient data (see app_platform_gate()).
do $$
declare
  t text;
begin
  foreach t in array array[
    'patients', 'patient_medical_flags', 'appointments', 'patient_packages', 'package_payments',
    'package_session_events', 'files', 'patient_consents', 'clinical_notes', 'clinical_note_addenda', 'clinical_note_versions',
    'conversations', 'messages', 'concern_events', 'reschedule_requests'
  ] loop
    execute format(
      -- Cheap first test: no signed-in user (patients, system work) → not a platform owner.
      'create policy %I on public.%I as restrictive for all to clinic_app
         using (public.app_current_user() is null or (select public.app_platform_gate()))
         with check (public.app_current_user() is null or (select public.app_platform_gate()))',
      t || '_platform_gate', t);
  end loop;
end $$;

-- Staff login tables: global by design (one person can work at several clinics).
-- What a user may see inside a clinic is decided by tenant_members, which IS isolated.
do $$
declare
  t text;
begin
  foreach t in array array['users', 'sessions', 'accounts', 'verifications', 'two_factors',
                           'global_rate_hits'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force row level security', t);
    execute format(
      'create policy %I on public.%I for all to clinic_app using (true) with check (true)',
      t || '_app_access', t);
  end loop;
end $$;
-- app_create_clinic() (runs as the table owner) checks that the caller is a platform owner.
create policy users_owner_lookup on public.users for select
  using (current_user <> 'clinic_app');

-- ─── Patient walls ──────────────────────────────────────────────────────────
-- When a PATIENT is signed in (role "patient"), every table is limited further ("restrictive" = AND):
--   * their own rows, and their family's (people they are guardian of) — nobody else's;
--   * their membership (plan, dates, included visits);
--   * their dental treatment plan (procedure + price = the estimate; never the chart or notes);
--   * a few clinic reference tables (branches, services, …) read-only;
--   * everything else (clinical notes, other patients, audit log, payments, staff logins…) invisible;
--   * NO writes at all: patient actions are checked by the app, then done by the booking engine.
do $$
declare
  t text;
  rule text;
begin
  foreach t in array array[
    'branches', 'departments', 'tenant_members', 'rooms', 'devices', 'services',
    'staff_schedules', 'patients', 'audit_logs',
    'tenant_settings', 'branch_holidays', 'patient_medical_flags', 'appointments',
    'time_blocks', 'reservations', 'reschedule_requests', 'package_templates',
    'patient_packages', 'package_payments', 'package_session_events', 'files',
    'consent_templates', 'patient_consents', 'clinical_notes', 'clinical_note_addenda', 'clinical_note_versions',
    'verification_codes', 'rate_limit_hits', 'patient_sessions',
    'conversations', 'messages', 'message_templates', 'message_dispatches', 'webhook_events',
    'push_log', 'consent_rules', 'concern_events',
    'push_subscriptions', 'notification_prefs', 'schedule_exceptions',
    'platform_statements', 'platform_payments', 'support_grants', 'service_practitioners',
    'care_team', 'billing_items', 'visit_charges', 'visit_orders', 'visit_checkouts',
    'dental_chart_entries', 'dental_plan_items', 'lab_cases',
    'membership_plans', 'patient_memberships', 'membership_payments', 'membership_visits',
    'lab_reports', 'lab_values', 'lab_requests', 'clinical_photos', 'users', 'sessions', 'accounts', 'verifications', 'two_factors', 'global_rate_hits'
  ] loop
    rule := case
      when t = 'patients' then 'id = public.app_patient() or guardian_id = public.app_patient()'
      when t in ('appointments', 'patient_packages', 'patient_consents', 'dental_plan_items', 'patient_memberships') then 'public.app_patient_scope(patient_id)'
      when t in ('branches', 'departments', 'services', 'rooms', 'tenant_members', 'consent_templates', 'consent_rules', 'tenant_settings') then 'true'
      else 'false'
    end;
    execute format(
      'create policy %I on public.%I as restrictive for all to clinic_app
         using (not public.app_is_patient() or (%s))
         with check (not public.app_is_patient())',
      t || '_patient_wall', t, rule);
  end loop;
end $$;

-- Push subscriptions and notification choices belong to one staff member. System work
-- (sending notifications, no signed-in user) may read them; a signed-in user sees only their own.
do $$
declare
  t text;
begin
  foreach t in array array['push_subscriptions', 'notification_prefs'] loop
    execute format(
      'create policy %I on public.%I as restrictive for all to clinic_app
         using (public.app_current_user() is null or user_id = public.app_current_user())
         with check (public.app_current_user() is null or user_id = public.app_current_user())',
      t || '_own_only', t);
  end loop;
end $$;


commit;

select 'Setup complete. You can now add DATABASE_URL to Vercel.' as result;
